#include "GameplayCombat3D.h"
#include <algorithm>

using namespace Aevrynd;
namespace GameplayLab {
void GameplayCombat3D::SpawnMonster(Vec3 position,float health){if(monsterCollider_)collision_.Destroy(monsterCollider_);if(monsterBody_)physics_.DestroyBody(monsterBody_);monster_={position,(std::max)(1.f,health),true};player_={GameplayPlayerMaximumHealth3D,true};attack_=Attack3D::None;nextAttack_=Attack3D::Attack1;attackClock_=0;aiClock_=0;windowSwept_=false;hitThisAttack_.clear();monsterAttackCooldown_=0;monsterAttackClock_=0;monsterAttackActive_=false;monsterAttackApplied_=false;stats_={};monsterCollider_=collision_.CreateBox({{position+Vec3{0,1,0},{.45f,1,.45f}},2,1,1,false});RigidBodySettings3D body{};body.type=RigidBodyType3D::Kinematic;body.transform.position=position+Vec3{0,1,0};body.colliderExtents={.45f,1,.45f};body.layer=2;body.collisionMask=1;monsterBody_=physics_.CreateBody(body);}
void GameplayCombat3D::BeginAttack(){attack_=nextAttack_;nextAttack_=attack_==Attack3D::Attack1?Attack3D::Attack2:attack_==Attack3D::Attack2?Attack3D::Attack3:Attack3D::Attack1;attackClock_=0;windowSwept_=false;hitThisAttack_.clear();}
void GameplayCombat3D::Sweep(const CombatInput3D& input){++stats_.sweeps;const Vec3 forward=Normalize(input.playerForward),center=input.playerPosition+Vec3{0,1,0}+forward*.7f;for(const auto handle:collision_.QueryBox(center,{GameplayMeleeContactReach3D,.9f,GameplayMeleeContactReach3D},{2,1,false})){if(!hitThisAttack_.insert(handle.value).second){++stats_.duplicateHits;continue;}const auto* collider=collision_.Get(handle);if(!collider||collider->userData!=1||!monster_.alive)continue;const float damage=attack_==Attack3D::Attack3?50.f:30.f;monster_.health=(std::max)(0.f,monster_.health-damage);++stats_.hits;if(monster_.health==0){monster_.alive=false;++stats_.kills;collision_.Destroy(monsterCollider_);physics_.DestroyBody(monsterBody_);monsterCollider_={};monsterBody_={};}}}
void GameplayCombat3D::Tick(const CombatInput3D& input,float deltaTime){deltaTime=Clamp(deltaTime,0,.1f);if(player_.alive&&input.attackPressed&&(attack_==Attack3D::None||attackClock_>.42f))BeginAttack();if(attack_!=Attack3D::None){attackClock_+=deltaTime;if(player_.alive&&!windowSwept_&&attackClock_>=.12f){Sweep(input);windowSwept_=true;}if(attackClock_>=.55f)attack_=Attack3D::None;}if(!monster_.alive||!player_.alive){monsterAttackActive_=false;monsterAttackApplied_=false;monsterAttackClock_=0;monsterAttackCooldown_=0;return;}aiClock_+=deltaTime;const Vec3 delta=input.playerPosition-monster_.position;const float distance=Length(delta);if(distance>GameplayMonsterStopDistance3D&&distance<12.f){monsterAttackActive_=false;monsterAttackApplied_=false;monsterAttackClock_=0;monsterAttackCooldown_=0;monster_.position=monster_.position+Normalize(delta)*deltaTime*1.8f;Transform3D transform{};transform.position=monster_.position+Vec3{0,1,0};physics_.SetTransform(monsterBody_,transform);collision_.UpdateBox(monsterCollider_,{{transform.position,{GameplayMonsterCapsuleRadius3D,1,GameplayMonsterCapsuleRadius3D}},2,1,1,false});return;}if(distance>GameplayMeleeContactReach3D||!input.playerDamageEnabled){monsterAttackActive_=false;monsterAttackApplied_=false;monsterAttackClock_=0;monsterAttackCooldown_=0;return;}if(!monsterAttackActive_){monsterAttackCooldown_+=deltaTime;if(monsterAttackCooldown_>=GameplayMonsterAttackCooldown3D){monsterAttackActive_=true;monsterAttackClock_=0;monsterAttackApplied_=false;++stats_.monsterAttacks;}return;}monsterAttackClock_+=deltaTime;if(!monsterAttackApplied_&&monsterAttackClock_>=GameplayMonsterAttackHitTime3D){monsterAttackApplied_=true;player_.health=(std::max)(0.f,player_.health-GameplayMonsterAttackDamage3D);++stats_.playerHits;if(player_.health==0.f){player_.alive=false;++stats_.playerDeaths;}}if(monsterAttackClock_>=GameplayMonsterAttackDuration3D){monsterAttackActive_=false;monsterAttackApplied_=false;monsterAttackClock_=0;monsterAttackCooldown_=0;}}
}
